    /// <summary>
    /// MPJ_5013_ExciseRegister by chaminda on 23 Feb 2022
    /// </summary>
    public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        METTariffItemCodeStaging    metTariffItemCodeStaging;
        ttsbegin;
            
        while select forupdate metTariffItemCodeStaging
            where metTariffItemCodeStaging .DefinitionGroup     == _dmfDefinitionGroupExecution.DefinitionGroup &&
                  metTariffItemCodeStaging .ExecutionId         == _dmfDefinitionGroupExecution.ExecutionId  &&
                  metTariffItemCodeStaging .TransferStatus      == DMFTransferStatus::NotStarted             &&
                  !metTariffItemCodeStaging.ValidTo


        {
            metTariffItemCodeStaging.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);      
            metTariffItemCodeStaging.ValidTo = dateMax();
            metTariffItemCodeStaging.doUpdate();                
            
        }
        ttscommit;
    }
